const fs = require('fs');
const path = require('path');

const dir = __dirname;
const entries = fs.readdirSync(dir, { withFileTypes: true });
const files = entries
  .filter((e) => e.isFile())
  .filter((e) => !e.name.startsWith('.'))
  .filter((e) => e.name !== 'backup-manifest.json')
  .map((e) => e.name)
  .sort();

fs.writeFileSync(
  path.join(dir, 'backup-manifest.json'),
  JSON.stringify({ files }, null, 2) + '\n'
);

console.log('Wrote backup-manifest.json with', files.length, 'files:', files);

